// Tiles: # wood (hookable)  X steel  ^ spikes  S switch (hit with hook)
// G gate, closed until a switch flips  g gate, open until a switch flips
// C rotten beam (hookable, breaks soon after the hook bites, regrows)
// D locked door (key)  H shutter (open while every _ plate is pressed)  E exit
// * shadow cloak (guards cannot see you)  + wind boots (double jump)  $ guardian charm (survive one hit)
// o gold coin (exit stays shut until every coin is taken)
// level.chase = px/s: a wall of fire sweeps in from the left
// F checkpoint flag (touch it and you respawn there)  O / Q teleport doors (two of each letter, linked)  I ice floor (solid, slippery)
// J spring pad (solid, launches you upward)  W updraft (rising air, lifts you while inside)
// P start  K key  B crate  T patrol guard  Y/U static guard facing left/right  V watcher (turns around)  ! patrol turn marker
// A flame vent (solid grate; every few seconds it flickers, then fires a column of flame up to 3 tiles high)
// L searchlight (hangs from above; its beam sweeps side to side and spots you if you stay in it)
// N crumbling floor (solid until you stand on it; cracks, falls away, regrows a few seconds later)
// > < conveyor (solid floor that carries you right or left; you cannot stand still on it)
// M crusher (iron ceiling mount; its stone weight shakes, slams down to the floor below, then winches back up)
// Z z blinking planks (Z is solid for half of every 3 s, z for the other half; they flicker before vanishing)
// R r arrow trap (a slot in the wall that shoots an arrow right / left every 2 s, at waist height, until it hits something solid)
// @ % saw blade (slides left-right / up-down along its track, which ends at anything solid or a ! marker)
// = | moving platform (a plank two tiles wide, marked on its left tile; slides left-right / up-down along its track and carries you)
// { } crosswind (open air; gusts left / right for 1.6 s of every 3.2 s, all in step, harder than you can run against)
// v icicle (hangs under a ceiling; walk beneath and it shakes, then drops; regrows a few seconds after it shatters)
// ~ deep snow (solid ground; half running speed, three-quarter jump height)
// ; creaky boards (solid floor; stepping on it makes every guard within 8 tiles turn to face you)
// & bell (solid; strike it with the hook and every guard within 7 tiles turns to face it)
